/**
 *  How much the Floor Manager may do through `ys` on its own.
 * 
 *  Destructive commands are refused at every level. See [`crate::coordinator::Action`].
 */
export type FloorManagerLevel = FloorManagerLevel_Serialize | FloorManagerLevel_Deserialize;

/**
 *  How much the Floor Manager may do through `ys` on its own.
 * 
 *  Destructive commands are refused at every level. See [`crate::coordinator::Action`].
 */
export type FloorManagerLevel_Deserialize = 
/**  Look. Every command that starts something or writes is refused. */
"read-only" | 
/**  Look. Every command that starts something or writes is refused. */
"read_only" | 
/**  Look. Every command that starts something or writes is refused. */
"readonly" | 
/**  Starts and writes wait for a yes in the app. The default. */
"ask" | 
/**
 *  May start agents, workspaces, workflows, tests and checkouts, and other writes that
 *  are not destructive, without asking.
 */
"trusted";

/**
 *  How much the Floor Manager may do through `ys` on its own.
 * 
 *  Destructive commands are refused at every level. See [`crate::coordinator::Action`].
 */
export type FloorManagerLevel_Serialize = 
/**  Look. Every command that starts something or writes is refused. */
"read-only" | 
/**  Starts and writes wait for a yes in the app. The default. */
"ask" | 
/**
 *  May start agents, workspaces, workflows, tests and checkouts, and other writes that
 *  are not destructive, without asking.
 */
"trusted";

/**  Which forge a host is, as far as the shape of its URLs goes. */
export type ForgeKind = "github" | "gitlab" | "bitbucket" | 
/**
 *  Gitea, Forgejo, and anything else self-hosted: assumed to speak GitHub's URL shapes,
 *  which the Gitea family does. A wrong guess costs a link that 404s, not data.
 */
"unknown";

/**
 *  A fork packet: what Yardsort recorded about a workspace, for an agent starting a new
 *  workspace on a new branch made from this one's. See `yardsort_core::activity::handoff`.
 */
export type ForkPacket = {
	/**  Markdown, sent after the user's own message, which is the new workspace's task. */
	text: string,
	/**
	 *  The branch to start the new one from: the workspace's own, as git has it now. `None`
	 *  when it is not on a branch, and there is nothing to fork.
	 */
	branch: string | null,
	/**  Files changed and not committed there: a fork starts from the commits, so these stay. */
	uncommitted: number,
};

/**  Whose reviews and comments count. */
export type FromFilter = 
/**
 *  Accounts other than the one `gh` posts as, which is the user's and every agent's: a
 *  teammate, a review bot.
 */
"others" | 
/**
 *  The user's account too, except while a run this trigger started is going: what is posted
 *  then is the agent's own answers.
 */
"anyone";

export type GitStatus = {
	path: string | null,
	/**  As `git --version` prints it, e.g. `git version 2.55.0`. */
	version: string | null,
};

/**
 *  A handoff packet: what Yardsort recorded about a workspace, as the opening prompt for the
 *  next agent there. See `yardsort_core::activity::handoff`.
 */
export type HandoffPacket = {
	/**  Markdown, for the composer's message box: the user reads and edits it before sending. */
	text: string,
	/**  How many agent runs and events stand behind it, for the line above the box. */
	runs: number,
	events: number,
};

export type HarnessDef = {
	/**  Stable key, recorded with sessions. */
	id: string,
	label: string,
	command: string,
	/**  Always passed. */
	baseArgs: string[],
	/**
	 *  What puts the agent in its "auto" permission mode: it acts on its own but keeps a check on
	 *  risky actions, rather than asking about everything or nothing. Passed only while
	 *  [`Self::auto_mode`] is on. Empty means the harness has no such mode.
	 */
	autoArgs?: string[],
	/**
	 *  Start every interactive session — new, resumed or forked — with [`Self::auto_args`].
	 *  Off unless the user turns it on: how much an agent may do unasked is their call.
	 */
	autoMode?: boolean,
	modelArgs: string[],
	effortArgs: string[],
	sessionArgs: string[],
	promptArgs: string[],
	/**
	 *  How to run this agent **non-interactively**, with `{prompt}` for the question: the
	 *  print / exec mode every agent has. Yardsort uses it to have the agent write a commit
	 *  message or a pull request — see [`crate::draft`]. Empty means this harness cannot, which
	 *  is the honest default for one we know nothing about.
	 */
	writeArgs?: string[],
	/**
	 *  What gives the agent background context — its system-prompt option — with `{context}`
	 *  for the text. Yardsort uses it on a new conversation for a short note that the
	 *  workspace's other conversations can be read (`docs/design/29-conversation-context.md`).
	 *  Empty means the harness has no such option, or it is not known to work.
	 */
	contextArgs?: string[],
	/**
	 *  The same for a resume or fork, after its args: what makes a continued conversation read a
	 *  new note. [`Self::context_args`] for a harness that builds its system prompt at each
	 *  launch (OMP, pi); for Claude Code, which keeps the prompt a conversation began with, those
	 *  plus `--system-prompt-snapshot off`. Empty for one that keeps it whatever it is passed
	 *  (Codex, Grok), where a note would be passed and never seen.
	 */
	resumeContextArgs?: string[],
	resumeArgs: string[],
	forkArgs: string[],
	/**  Effort levels to offer. Empty hides the picker. */
	efforts: string[],
	/**  Model suggestions. Free text is always accepted: names change faster than we ship. */
	models: string[],
	promptTransport: PromptTransport,
	sessionIdMode: SessionIdMode,
	/**
	 *  With the `stdin` transport: how long the harness must have been quiet, after printing
	 *  something, before the prompt is pasted.
	 */
	stdinReadyMs: number,
	/**  Disabled harnesses stay configured but are not offered. */
	enabled: boolean,
	/**
	 *  In the user's words, what this harness is good at. Assist uses it to suggest a harness
	 *  for a task; harnesses without one are never suggested. Empty for every built-in: which
	 *  agent suits which work is the user's call, not ours.
	 */
	strengths?: string,
	/**
	 *  What to type into the agent to have it summarise its conversation and free its context,
	 *  e.g. `/compact`. Offered when the agent reports a context that is nearly full — see
	 *  [`crate::activity::context`]. `None` for an agent that has no such command or does not
	 *  report its context.
	 */
	compactCommand?: string | null,
};

/**  A harness definition plus whether its command can be found on this machine. */
export type HarnessInfo = {
	/**  Where `command` resolved to on the user's `PATH`; `None` if it is not installed. */
	resolvedPath: string | null,
	/**  Ships with Yardsort (as opposed to one the user added). */
	builtin: boolean,
	/**  A built-in whose definition the user has changed. */
	modified: boolean,
} & HarnessDef;

/**  The exact command lines a definition produces, for the settings form to show. */
export type HarnessPreview = {
	resolvedPath: string | null,
	start: string[],
	resume: string[],
	fork: string[],
	/**  Why this definition cannot be saved as it stands, if it cannot. */
	problem: string | null,
};

/**  Which harness to start, and with what. */
export type HarnessRequest = {
	id: string,
	/**  `None` or empty: let the harness use its own default. */
	model: string | null,
	effort: string | null,
	/**  The first message. `None` or empty just opens the harness. */
	prompt: string | null,
	/**
	 *  The first message is a handoff packet Yardsort assembled (see `activity::handoff`),
	 *  not the user's own task: it is sent like any prompt, but the session's record keeps no
	 *  prompt, so the workspace's task — what Assist and the next packet read — stays the
	 *  user's words.
	 */
	handoff?: boolean,
	/**
	 *  Leave the project's memory out of this launch's first message, though the project shares
	 *  it. The composer's per-launch opt-out; see `crate::memory`.
	 */
	skipMemory?: boolean,
	/**
	 *  Give the approved entries only, without the request to propose more, and nothing at all
	 *  when none is approved. For launches the user did not make by hand: a workflow that
	 *  starts five reviewers must not leave five proposals about that one review.
	 */
	quietMemory?: boolean,
	/**
	 *  Do not tell this agent about the workspace's other conversations, though the project
	 *  shares them: Alt-click on an agent button, or the composer's box. See
	 *  `docs/design/29-conversation-context.md`.
	 */
	skipContext?: boolean,
	/**
	 *  Sent to the agent after the first message, and only to the agent: the record keeps the
	 *  message alone as the task. A fork's packet (see `activity::handoff`), which carries the
	 *  project's memory already, so it goes in the memory's place.
	 */
	forkPacket?: string | null,
};

export type HarnessStatus = {
	id: string,
	label: string,
	command: string,
	enabled: boolean,
	/**  Where the command was found; `None` if it is not installed (or not on `PATH`). */
	path: string | null,
	/**  How to get it. Known for the built-in harnesses only. */
	install: InstallHint | null,
};

