	text: string,
	/**  `candidate`, `approved`, `rejected` or `revoked`. */
	state: string,
	/**  `user` or `agent`. */
	author: string,
	/**  Where it came from, in words: "the user", or "claude in fix-login". */
	from: string,
	createdAt: number | null,
	updatedAt: number | null,
	history: MemoryHistoryItem[],
